import{z as A,x as i,o as s,c as d,q as B,j as n,D as r,d as E,s as o,S as t,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"时钟恢复与扰码","description":"","frontmatter":{"title":"时钟恢复与扰码","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/clock-recovery-scrambling.md","filePath":"cs/clock-recovery-scrambling.md","lastUpdated":1791063341000}'),C={name:"cs/clock-recovery-scrambling.md"};function p(c,a,D,m,h,u){const l=i("Mermaid");return s(),d("div",null,[a[2]||(a[2]=B('<h1 id="时钟恢复与扰码" tabindex="-1">时钟恢复与扰码 <a class="header-anchor" href="#时钟恢复与扰码" aria-label="Permalink to &quot;时钟恢复与扰码&quot;">​</a></h1><div class="epigraph"><p>串行链路不另送时钟；接收机从跳变里锁相。扰码把用户数据打成伪随机，避免线路码之后仍出现病理游程。</p><footer>—— 据 IEEE 802.3 64B/66B 与扰码条款；Gardner, Phaselock Techniques 整理</footer></div><p><a href="/cs/line-coding">上一课</a>用块编码保证跳变。10G 以后改 64B/66B：同步头只有 2 比特，数据块本身可能仍长 0。缺口是<strong>时钟恢复（CDR）<strong>与</strong>扰码</strong>：锁相从边沿取定时；扰码器用自同步或帧同步多项式打散能量。本课不把铜缆衰减曲线画完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>符号率在吉赫兹，无法再并一根时钟线（相对早期并行总线）。接收 VCO/数字 CDR 跟踪相位；低频抖动用环路带宽折中。若净荷全零，即使 66 比特块有同步头，频谱仍可能有线谱，EMI 与 CDR 都差。扰码（如 \\(x^{58}+x^{39}+1\\) 一类 IEEE 多项式）使输出接近白，且对偶发错误不灾难性扩散——自同步扰码误码增殖有限，帧同步则要边界。</p><p>不要把扰码当成加密：多项式公开，状态可被观察。<span class="marginnote">常见误区：看到「伪随机」三个字就当成保密手段。扰码多项式写在 IEEE 802.3 标准里，任何人拿到比特流都能解扰；它的本职是让 0/1 统计上接近白噪声——喂饱 CDR 的跳变需求、压低 EMI。真正的保密要靠上层 TLS/IPsec，与本层无关。</span></p><p><span class="marginnote">64B/66B 见 IEEE 802.3 Clause 49。CDR 是锁相环，不是 MAC 状态机。本课不推 Gardner 鉴定器全文。</span></p><h3 id="扰码不是加密" tabindex="-1">扰码不是加密 <a class="header-anchor" href="#扰码不是加密" aria-label="Permalink to &quot;扰码不是加密&quot;">​</a></h3><p>多项式公开，状态可被观察。CDR 跟的是边沿，不是 MAC 状态机。丢锁表现为口 down，排障应先看 PHY，再看 STP。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>PCS：64 比特 → 加 2 比特同步头 → 扰码 → 串行。接收：CDR 抽样 → 解扰 → 找同步头锁定块边界。丢失锁定则链路 fault，上层看到 carrier down，不是 TCP 超时本身。<span class="marginnote">直觉类比：CDR 像跟着领舞者跳舞——不看秒表，只盯对方的动作节奏微调自己。本地振荡器（VCO）是自己的节拍，鉴相器发现「边沿总比我早」就加快一点、总比我晚就放慢一点，最终锁进同一节奏，把抽样时刻稳在每比特的中央。</span></p>',11)),(s(),n(t,null,{default:r(()=>[o(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20BLK%5B%2264B%20%2B%20%E5%90%8C%E6%AD%A5%E5%A4%B4%22%5D%20--%3E%20SCR%5B%22%E6%89%B0%E7%A0%81%22%5D%0A%20%20SCR%20--%3E%20SER%5B%22%E4%B8%B2%E8%A1%8C%22%5D%0A%20%20SER%20--%3E%20CDR%5B%22%E9%94%81%E7%9B%B8%E6%8A%BD%E6%A0%B7%22%5D%0A%20%20CDR%20--%3E%20DSCR%5B%22%E8%A7%A3%E6%89%B0%E4%B8%8E%E5%9D%97%E9%94%81%E5%AE%9A%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,[E("容量与调制假定接收机知道抽样时刻。本课把「知道」做成环路：跟踪频差与慢漂移。交换机端口 up/down 往往先死在 CDR/块锁，而不是 STP。主干"),e("a",{href:"/cs/frame-mac"},"帧"),E("的前导码在铜缆千兆仍帮对齐；高速串行则把对齐下放到 PCS 同步头。")],-1)),a[5]||(a[5]=e("p",null,"扰码与 8B/10B 分工：后者保证局部游程；前者在低开销块码上保证统计跳变。",-1)),(s(),n(t,null,{default:r(()=>[o(l,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20RX%5B%22%E5%8F%AA%E6%9C%89%E6%95%B0%E6%8D%AE%E3%80%81%E6%B2%A1%E6%9C%89%E6%97%B6%E9%92%9F%E7%BA%BF%E7%9A%84%E4%B8%B2%E8%A1%8C%E6%B5%81%22%5D%20--%3E%20PD%5B%22%E9%89%B4%E7%9B%B8%E5%99%A8%E7%9B%AF%E4%BD%8F%E6%AF%8F%E4%B8%AA%E8%B7%B3%E5%8F%98%E8%BE%B9%E6%B2%BF%22%5D%0A%20%20PD%20--%3E%20CMP%7B%22%E8%BE%B9%E6%B2%BF%E6%80%BB%E6%AF%94%E6%9C%AC%E5%9C%B0%20VCO%20%E6%97%A9%E8%BF%98%E6%98%AF%E6%99%9A%EF%BC%9F%22%7D%0A%20%20CMP%20--%3E%7C%22%E5%81%8F%E6%97%A9%22%7C%20FAST%5B%22%E8%B0%83%E5%BF%AB%E6%9C%AC%E5%9C%B0%E6%8C%AF%E8%8D%A1%22%5D%0A%20%20CMP%20--%3E%7C%22%E5%81%8F%E6%99%9A%22%7C%20SLOW%5B%22%E8%B0%83%E6%85%A2%E6%9C%AC%E5%9C%B0%E6%8C%AF%E8%8D%A1%22%5D%0A%20%20FAST%20--%3E%20LOCK%5B%22%E7%8E%AF%E8%B7%AF%E9%94%81%E5%AE%9A%EF%BC%9A%E6%8A%BD%E6%A0%B7%E7%82%B9%E7%A8%B3%E5%9C%A8%E6%AF%94%E7%89%B9%E4%B8%AD%E5%A4%AE%22%5D%0A%20%20SLOW%20--%3E%20LOCK%0A%20%20LOCK%20--%3E%20DSS%5B%22%E5%AF%B9%E9%BD%90%E5%90%8C%E6%AD%A5%E5%A4%B4%E5%90%8E%E8%A7%A3%E6%89%B0%E8%BE%93%E5%87%BA%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=B('<p><span class="marginnote">这张图回答「不送时钟线，定时是从哪来的」：答案是从数据自身的跳变里闭环锁出来的。这也解释了为什么全 0 或长串不变化的净荷是灾难——没有边沿可盯，环路失去参照；扰码保证跳变密度，就是在保护这条环路的粮食。</span></p><p><span class="marginnote">数字实例「误码增殖」：多项式 \\(x^{58}+x^{39}+1\\) 的反馈链横跨 58 个比特，线路上错 1 比特，解扰时会顺着这条链把后面几十比特一并污染再自愈。帧同步扰码每帧重置状态、错误不扩散，代价是要先锁定块边界——这就是 64B/66B 要那 2 比特同步头的原因之一。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 SerDes 的 FFE/DFE 抽头训练全集（那是铜缆均衡）。介质衰减与光纤是下一课。后课默认：无独立时钟线；扰码公开且为频谱服务。</p><p>病理图案仍可能通过短周期测试向量构造，标准用禁则与测试模式排除，不在课上穷举。</p><p>下一课<a href="/cs/copper-fiber-media">铜缆、光纤与衰减</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CDR 从数据边沿恢复波特时钟。</li><li>扰码打散能量，不是保密。</li><li>64B/66B 用低开销同步头加扰码替代重块码。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：IEEE 802.3 Clause 49；Gardner。</li></ul>',8))])}const S=A(C,[["render",p]]);export{f as __pageData,S as default};
